window.addEventListener('keydown',e=>{if(e.key==='Escape'){cancelTool();renderContext();return;}if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('redo'):$('undo')).click();return;}if(e.key.toLowerCase()==='r'&&tool?.kind==='place'){tool.rotation=(tool.rotation+15)%360;return;}if(!selectedObject())return;const o=selectedObject();if(['Delete','Backspace'].includes(e.key)){e.preventDefault();perform({type:'remove-object',id:o.id},{select:{type:'floor',id:o.room_id}});}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const p=[...o.position_m],step=e.shiftKey?.5:.1;p[0]+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;p[2]+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;perform({type:'move-object',id:o.id,position_m:p});}});
function changeSummary(){const before=draft.original,after=draft.house,out=[];for(const f of after.storeys){const b=before.storeys.find(x=>x.level===f.level);for(const o of f.objects){const old=b.objects.find(x=>x.id===o.id);if(!old)out.push(`Added ${title(o.role)}`);else if(JSON.stringify(old)!==JSON.stringify(o))out.push(`Moved or updated ${title(o.role)}`);}for(const o of b.objects)if(!f.objects.some(x=>x.id===o.id))out.push(`Removed ${title(o.role)}`);if(JSON.stringify(f.rooms)!==JSON.stringify(b.rooms)||JSON.stringify(f.walls)!==JSON.stringify(b.walls))out.push(`Changed rooms or walls on floor ${f.level+1}`);if(JSON.stringify(f.finish_regions)!==JSON.stringify(b.finish_regions))out.push(`Changed local floor materials on floor ${f.level+1}`);}if(JSON.stringify(before.envelope?.windows)!==JSON.stringify(after.envelope?.windows))out.push('Changed window layout');if(Boolean(before.signage)!==Boolean(after.signage)||(after.signage&&!sameSignage(before.signage,after.signage)))out.push(after.signage?'Changed the shop sign':'Removed the shop sign');return out.length?out:['No changes yet.'];}
$('review').onclick=()=>{if(!handoff)return;const result=validateDraft(draft);$('review-copy').textContent=`Apply to ${handoff.target.label} in your saved world.`;$('review-summary').replaceChildren(...changeSummary().map(line=>el('div',line)));$('review-warning').textContent=result.valid?'Your design passed the checks.':`${result.issues.length} issues must be resolved before applying.`;$('confirm-apply').disabled=!result.valid;$('confirm-apply').textContent=handoff.target.propertyKind==='business'?'Apply to my business':'Apply to my home';$('review-dialog').showModal();};
$('confirm-apply').onclick=()=>{try{const saved=applyToWorld(handoff,draft);pendingRevision=saved.revision;$('review-dialog').close();$('mode-note').textContent='Design queued · keep your Kerbside world open.';toast('Waiting for your world to accept this design.');}catch(e){$('review-warning').textContent=e.message;}};
window.addEventListener('storage',event=>{if(event.key!==`${PREFIX}receipt:${pendingRevision}`||!event.newValue)return;try{const receipt=JSON.parse(event.newValue);$('mode-note').textContent=receipt.state==='applied'?'Applied to your saved world · furniture, walls and finishes updated':`Not applied: ${receipt.message}`;toast(receipt.state==='applied'?'Your world accepted the new interior.':receipt.message);if(finishing){if(receipt.state==='applied'){removeDraft(draftKey(handoff));finishReturn(true);}else{finishing=false;$('discard-editing').disabled=false;$('continue-editing').disabled=false;$('save-finished').disabled=false;$('save-finished').textContent='Save changes';$('finish-note').textContent=receipt.message;}}}catch{}});
function fillLibrary(){const old=$('house').value,group=$('space-category').value;$('house').replaceChildren(...(initialHandoff?[option('home',`${initialHandoff.target.label} · your space`)]:[]),...records.map((r,i)=>({r,i})).filter(({r})=>group==='all'||r.group===group).map(({r,i})=>option(i,r.name||r.id)));if([...$('house').options].some(o=>o.value===old))$('house').value=old;}
$('house').onchange=async()=>{const seq=++loadSeq;if($('house').value==='home'&&initialHandoff){loadHouse(initialHandoff.house,initialHandoff);$('space-dialog').close();return;}const record=records[Number($('house').value)];if(!record)return;try{const response=await fetch(record.url);if(!response.ok)throw Error(`HTTP ${response.status}`);const h=await response.json();if(seq!==loadSeq)return;loadHouse(h);$('space-dialog').close();}catch(e){if(seq===loadSeq)toast(`Could not load space: ${e.message}`);}};
$('space-category').onchange=()=>{fillLibrary();};
async function start(){try{
 const [homes,residential,library,businesses,restaurants,stores]=await Promise.all(['../inferred-interiors/manifest.json','../inferred-residential/manifest.json','../interior-assets/manifest.json','./businesses/manifest.json','../inferred-restaurants/manifest.json','../inferred-stores/manifest.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error(`Could not load ${url}`);return r.json();}));
 records=[...homes.houses.filter(h=>h.file).map(h=>({...h,group:'Homes',url:`../inferred-interiors/${h.file}`})),...residential.houses.filter(h=>h.file).map(h=>({...h,group:'Homes',url:`../inferred-residential/${h.file}`})),...businesses.houses.map(h=>({...h,url:`./businesses/${h.file}`})),...restaurants.houses.filter(h=>h.file).map(h=>({...h,group:'Food & drink',url:`../inferred-restaurants/${h.file}`})),...stores.houses.filter(h=>h.file).map(h=>({...h,group:'Retail',url:`../inferred-stores/${h.file}`}))];
 catalogue=[...library.assets.filter(a=>a.model&&a.role&&a.dimensions_m?.every(v=>Number.isFinite(v)&&v>0)).map(a=>({...a,...(a.role==='picture'?{mount:'wall'}:/ceiling_lamp|bulb/.test(a.role)?{mount:'ceiling'}:{})})),...Object.entries(FIXTURES).filter(([role])=>!library.assets.some(a=>a.role===role)).map(([role,dimensions_m])=>({id:'procedural:'+role,name:title(role),role,dimensions_m,procedural:true,license:'Kerbside procedural geometry'})),...WALL_ITEMS].map(a=>({...a,...(!a.mount&&a.role==='picture'?{mount:'wall'}:!a.mount&&/ceiling_lamp|bulb/.test(a.role)?{mount:'ceiling'}:!a.mount&&/^(table_item|counter_item|cutting_board|table_lamp|medical_item|payment_terminal|shelf_item|bath_item)$/.test(a.role)?{mount:'surface'}:{})}));
 $('catalogue-type').append(...[...new Set(catalogue.map(a=>a.role))].sort().map(role=>option(role,title(role))));preview=new CataloguePreviews({loadAsset,assetBase});initialHandoff=loadHandoff();fillLibrary();if(initialHandoff){$('house').value='home';loadHouse(initialHandoff.house,initialHandoff);}else{const id=new URLSearchParams(location.search).get('building')||'stress-family',index=Math.max(0,records.findIndex(r=>r.id===id));$('house').value=String(index);$('house').dispatchEvent(new Event('change'));}
 }catch(e){$('empty').hidden=false;$('empty').textContent=`Could not start: ${e.message}`;toast(e.message);}}
function finishReturn(saved){$('finish-dialog').close();if(embedded&&parent!==window)parent.postMessage({type:'kerbside:interior:finished',token:handoff.token,saved,revision:pendingRevision},location.origin);else toast(saved?'Design saved.':'Changes discarded.');}
$('finish').onclick=()=>{const check=validateDraft(draft);$('finish-note').textContent=check.valid?'Save your changes to return to Kerbside, or discard this edit.':`${check.issues.length} design issues must be resolved before saving. You can keep editing or discard this edit.`;$('save-finished').disabled=!check.valid;$('finish-dialog').showModal();};
$('finish-dialog').addEventListener('cancel',e=>{if(finishing)e.preventDefault();});$('continue-editing').onclick=()=>{if(!finishing)$('finish-dialog').close();};$('discard-editing').onclick=()=>{$('finish-dialog').close();$('discard-dialog').showModal();};$('keep-changes').onclick=()=>$('discard-dialog').close();
$('confirm-discard').onclick=()=>{removeDraft(draftKey(handoff||draft.house));$('discard-dialog').close();finishReturn(false);};
$('save-finished').onclick=()=>{if(finishing)return;if(!handoff){saveDraft(draftKey(draft.house),draft);finishReturn(true);return;}try{const saved=applyToWorld(handoff,draft);pendingRevision=saved.revision;finishing=true;$('discard-editing').disabled=true;$('continue-editing').disabled=true;$('save-finished').disabled=true;$('save-finished').textContent='Saving…';$('finish-note').textContent='Waiting for Kerbside to save and rebuild your interior…';}catch(e){$('finish-note').textContent=e.message;}};
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent||event.data?.token!==handoff?.token||event.data?.type!=='kerbside:interior:finish-error')return;finishing=false;$('discard-editing').disabled=false;$('continue-editing').disabled=false;$('save-finished').disabled=false;$('save-finished').textContent='Save changes';$('finish-note').textContent=event.data.message;$('finish-dialog').showModal();});


// ---- the shop's sign (businesses): what carries the name over the door, how it is lettered, and
// a line under it. Kept on the design's house (house.signage: signage.mjs), so it is saved,
// undone and applied with the layout; the city draws it over the shop's door.
const signName=()=>handoff?.target?.propertyKind==='business'&&handoff.target.label?handoff.target.label:(draft?.house.name||draft?.house.business_name||'Your shop');
const signNow=()=>normalizeSignage(draft.house.signage)||normalizeSignage({});
function setSignage(next){const sign=next?normalizeSignage(next):null;if(sign&&draft.house.signage&&sameSignage(sign,draft.house.signage))return;if(!sign&&!draft.house.signage)return;const d=copy(draft);d.past.push(copy(draft.house));d.future=[];if(sign)d.house.signage=sign;else delete d.house.signage;draft=d;refresh({catalog:false});renderSignage();}
function drawSignPreview(){const canvas=$('signage-preview'),s=signNow(),L=signLayout(s,signName(),5),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height;ctx.clearRect(0,0,W,H);
 // The front it goes on: a wall, a door and a window, then the sign as it will stand over them.
 ctx.fillStyle='#cfc8b8';ctx.fillRect(0,0,W,H);ctx.fillStyle='#6c7a86';ctx.fillRect(W*0.56,H*0.5,W*0.3,H*0.34);ctx.fillStyle='#3b3f44';ctx.fillRect(W*0.2,H*0.46,W*0.16,H*0.54);ctx.fillStyle='#9a968c';ctx.fillRect(0,H*0.94,W,H*0.06);
 const scale=Math.min((W*0.8)/L.width,(H*0.3)/L.height),pw=Math.round(L.width*scale),ph=Math.round(L.height*scale),x=Math.round((W-pw)/2),y=Math.round(H*0.1);
 const panel=document.createElement('canvas');panel.width=Math.max(8,pw);panel.height=Math.max(8,ph);
 const ground=s.medium==='awning'?s.awning.colour:s.medium==='painted'?null:s.board.colour;
 drawSign(panel.getContext('2d'),s,L,panel.width,panel.height,s.medium==='awning'&&s.awning.type==='striped'?{stripes:[s.awning.colour,s.awning.stripe]}:{ground});
 if(s.medium==='awning'){ctx.fillStyle=s.awning.colour;ctx.beginPath();if(s.awning.type==='dome'){ctx.ellipse(W/2,y+2,pw/2,H*0.09,0,Math.PI,0);}else if(s.awning.type==='flat'){ctx.rect(x,y-6,pw,8);}else{ctx.moveTo(x+pw*0.06,y-H*0.09);ctx.lineTo(x+pw*0.94,y-H*0.09);ctx.lineTo(x+pw,y+2);ctx.lineTo(x,y+2);}ctx.fill();
  if(s.awning.type==='striped'){const n=Math.max(6,Math.round(L.width/0.3));ctx.save();ctx.beginPath();ctx.moveTo(x+pw*0.06,y-H*0.09);ctx.lineTo(x+pw*0.94,y-H*0.09);ctx.lineTo(x+pw,y+2);ctx.lineTo(x,y+2);ctx.clip();ctx.fillStyle=s.awning.stripe;for(let i=1;i<n;i+=2)ctx.fillRect(x+i*pw/n,y-H*0.09,pw/n,H*0.09+2);ctx.restore();}}
 if(s.medium==='standing'){const sx=Math.round(W*0.42),sy=Math.round(H*0.52),sh=Math.round(H*0.34),sw=Math.round(sh*L.width/L.height);ctx.fillStyle='#2b2f33';ctx.fillRect(sx+4,sy+sh,4,H*0.1);ctx.fillRect(sx+sw-8,sy+sh,4,H*0.1);ctx.drawImage(panel,sx,sy,sw,sh);return;}
 ctx.drawImage(panel,x,y);}
function renderSignage(){const s=signNow(),set=draft.house.signage,form=$('signage-form');
 const choose=(label,table,value,change)=>{const wrap=el('div'),id='sign-'+label.replace(/\W/g,''),field=el('select',null,{id});wrap.append(el('label',label,{for:id}));field.append(...Object.entries(table).map(([key,v])=>option(key,typeof v==='string'?v:v.label||title(key))));field.value=value;field.onchange=()=>change(field.value);wrap.append(field);return wrap;};
 const paint=(label,value,change)=>{const wrap=el('div'),id='sign-'+label.replace(/\W/g,''),field=el('input',null,{id,type:'color',value});wrap.append(el('label',label,{for:id}));field.onchange=()=>change(field.value);wrap.append(field);return wrap;};
 const sizes=Object.fromEntries(Object.entries(NAME_SIZES).map(([k,m])=>[k,`${title(k)} (${Math.round(m*100)} cm letters)`]));
 const rows=[choose('Where the name goes',SIGN_MEDIA,s.medium,v=>setSignage({...s,medium:v}))];
 if(s.medium==='awning'){rows.push(choose('Awning type',AWNING_TYPES,s.awning.type,v=>setSignage({...s,awning:{...s.awning,type:v}})),paint('Awning colour',s.awning.colour,v=>setSignage({...s,awning:{...s.awning,colour:v}})));if(s.awning.type==='striped')rows.push(paint('Stripe colour',s.awning.stripe,v=>setSignage({...s,awning:{...s.awning,stripe:v}})));}
 if(s.medium==='board'||s.medium==='standing')rows.push(paint('Sign colour',s.board.colour,v=>setSignage({...s,board:{colour:v}})));
 rows.push(choose('Lettering',NAME_STYLES,s.name.style,v=>setSignage({...s,name:{...s.name,style:v}})),choose('Name size',sizes,s.name.size,v=>setSignage({...s,name:{...s.name,size:v}})),paint('Name colour',s.name.colour,v=>setSignage({...s,name:{...s.name,colour:v}})));
 const tag=el('div'),field=el('input',null,{id:'sign-tagline',type:'text',maxlength:String(TAGLINE_MAX),placeholder:'A slogan, or what you sell: Beer · Wine · Spirits',value:s.tagline.text});tag.className='wide-field';tag.append(el('label','Line under the name (optional)',{for:'sign-tagline'}),field);field.onchange=()=>setSignage({...s,tagline:{...s.tagline,text:field.value}});rows.push(tag);
 if(s.tagline.text)rows.push(paint('Line colour',s.tagline.colour,v=>setSignage({...s,tagline:{...s.tagline,colour:v}})));
 form.replaceChildren(...rows);$('signage-name').textContent=signName();$('signage-state').textContent=set?'This sign is part of your design: it goes up over your door when you apply it.':'No sign of your own yet: change anything here to start one.';$('signage-remove').disabled=!set;drawSignPreview();}
$('signage').onclick=()=>{if(!draft||!isBusiness(draft.house))return;renderSignage();$('signage-dialog').showModal();};
$('signage-remove').onclick=()=>setSignage(null);
$('signage-done').onclick=()=>{if(!draft.house.signage)setSignage(signNow());$('signage-dialog').close();};

start();
